 30→func (c *CopilotCLI) IsTransientError(out Output, err error) bool {
 31→	if errors.Is(err, context.DeadlineExceeded) {
 32→		return true
 33→	}
 34→	combined := out.Stdout + out.Stderr
 35→	for _, p := range []string{
 36→		"overloaded",
 37→		"rate limit",
 38→		"503",
 39→		"529",
 40→		"ECONNRESET",
 41→		"ETIMEDOUT",
 42→		"Too Many Requests",
 43→		// gpt-4.1 sometimes calls Copilot's Edit tool without old_str,
 44→		// resulting in zero code changes despite a successful exit.
 45→		"old_str is required",
 46→	} {
 47→		if strings.Contains(combined, p) {
 48→			return true
 49→		}
 50→	}
 51→	return false
 52→}
