 60→func (c *CopilotCLI) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
 61→	cfg := &runConfig{Model: "gpt-4.1"}
 62→	for _, o := range opts {
 63→		o(cfg)
 64→	}
 65→
 66→	timeout := 60 * time.Second
 67→	if cfg.PromptTimeout > 0 {
 68→		timeout = cfg.PromptTimeout
 69→	}
 70→	promptCtx, cancel := context.WithTimeout(ctx, timeout)
 71→	defer cancel()
 72→
 73→	args := []string{"-p", prompt, "--model", cfg.Model, "--allow-all"}
 74→	displayArgs := []string{"-p", fmt.Sprintf("%q", prompt), "--model", cfg.Model, "--allow-all"}
 75→	cmd := exec.CommandContext(promptCtx, c.Binary(), args...)
 76→	cmd.Dir = dir
 77→	cmd.Stdin = nil
 78→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
 79→	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
 80→	cmd.Cancel = func() error {
 81→		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
 82→	}
 83→	cmd.WaitDelay = 5 * time.Second
 84→
 85→	var stdout, stderr strings.Builder
 86→	cmd.Stdout = &stdout
 87→	cmd.Stderr = &stderr
 88→
 89→	err := cmd.Run()
 90→	exitCode := 0
 91→	if err != nil {
 92→		exitErr := &exec.ExitError{}
 93→		if errors.As(err, &exitErr) {
 94→			exitCode = exitErr.ExitCode()
 95→		} else {
 96→			exitCode = -1
 97→		}
 98→		if promptCtx.Err() == context.DeadlineExceeded {
 99→			err = fmt.Errorf("%w: %w", err, context.DeadlineExceeded)
100→		}
101→	}
102→
103→	out := Output{
104→		Command:  c.Binary() + " " + strings.Join(displayArgs, " "),
105→		Stdout:   stdout.String(),
106→		Stderr:   stderr.String(),
107→		ExitCode: exitCode,
108→	}
109→
110→	// gpt-4.1 sometimes calls Copilot's Edit tool without required parameters,
111→	// producing zero code changes despite exit 0. Surface this as an error so
112→	// the transient-error retry mechanism can restart the scenario.
113→	// Only trigger when copilot reports zero changes — it may retry internally.
114→	if err == nil && strings.Contains(out.Stdout, "old_str is required") &&
115→		strings.Contains(out.Stderr, "Total code changes:     +0 -0") {
116→		err = errors.New("copilot Edit tool failed: old_str is required")
117→	}
118→
119→	return out, err
120→}
